command:
cat > /etc/nginx/conf.d/https-8443.conf <<'ANTRIEB_EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;

    ssl_certificate     /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;
    ssl_protocols       TLSv1.2 TLSv1.3;

    location / {
        default_type text/plain;
        return 200 "node1 HTTPS service is healthy\n";
    }
}
ANTRIEB_EOF
restorecon -F /etc/nginx/conf.d/https-8443.conf
printf 'HTTP_PORT_CONTEXT\n'; semanage port -l 2>/dev/null | grep '^http_port_t' || true
printf 'CONFIG_TEST\n'; nginx -t

